changeSet.sql:
CREATE TABLE nexus.reembed_jobs ( tenant_id TEXT NOT NULL, job_id UUID NOT NULL, source_collection TEXT NOT NULL, target_collection TEXT NOT NULL, state TEXT NOT NULL, disposition TEXT, doc_cursor TEXT NOT NULL DEFAULT '', pass_number SMALLINT NOT NULL DEFAULT 1, cutover_step TEXT, documents_moved BIGINT NOT NULL DEFAULT 0, documents_skipped BIGINT NOT NULL DEFAULT 0, chunks_embedded BIGINT NOT NULL DEFAULT 0, chunks_reused BIGINT NOT NULL DEFAULT 0, tokens_billed BIGINT NOT NULL DEFAULT 0, token_cap BIGINT, keep_source BOOLEAN NOT NULL DEFAULT false, force_delete BOOLEAN NOT NULL DEFAULT false, started_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, finished_at TIMESTAMPTZ, failure_reason TEXT, last_error TEXT, CONSTRAINT reembed_jobs_pk PRIMARY KEY (tenant_id, job_id), CONSTRAINT reembed_jobs_state_check CHECK (state IN ('planned', 'running', 'paused', 'failed', 'aborted', 'cutover', 'done', 'done_with_skips')), CONSTRAINT reembed_jobs_disposition_check CHECK (disposition IS NULL OR disposition IN ('deleted', 'kept_by_flag', 'kept_tombstoned', 'kept_residue', 'revived')), CONSTRAINT reembed_jobs_cutover_step_check CHECK (cutover_step IS NULL OR cutover_step IN ('superseded', 'delete_started')), CONSTRAINT reembed_jobs_failure_reason_check CHECK (failure_reason IS NULL OR failure_reason IN ('batch_failed', 'profile_changed', 'token_cap', 'parity_mismatch')) );
-- The source lock: one live-or-resumable job per (tenant, source collection). CREATE UNIQUE INDEX reembed_jobs_source_lock ON nexus.reembed_jobs (tenant_id, source_collection) WHERE state IN ('planned', 'running', 'paused', 'cutover', 'failed');
CREATE TABLE nexus.reembed_job_moves ( tenant_id TEXT NOT NULL, job_id UUID NOT NULL, doc_id TEXT NOT NULL, outcome TEXT NOT NULL, reason TEXT, pass_number SMALLINT NOT NULL, at TIMESTAMPTZ NOT NULL, CONSTRAINT reembed_job_moves_pk PRIMARY KEY (tenant_id, job_id, doc_id), CONSTRAINT reembed_job_moves_job_fk FOREIGN KEY (tenant_id, job_id) REFERENCES nexus.reembed_jobs (tenant_id, job_id) ON DELETE CASCADE, CONSTRAINT reembed_job_moves_outcome_check CHECK (outcome IN ('moved', 'skipped')) );

ALTER TABLE nexus.reembed_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.reembed_jobs FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.reembed_jobs
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

ALTER TABLE nexus.reembed_job_moves ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.reembed_job_moves FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.reembed_job_moves
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

changeSet.rollback:
DROP POLICY IF EXISTS tenant_isolation ON nexus.reembed_job_moves;
ALTER TABLE nexus.reembed_job_moves NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.reembed_job_moves DISABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON nexus.reembed_jobs;
ALTER TABLE nexus.reembed_jobs NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.reembed_jobs DISABLE ROW LEVEL SECURITY;
